      "proposed_laureates": [
        "Charles L. Bennett",
        "Lyman A. Page",
        "David N. Spergel"
      ],
      "assessment": {
        "nobel_worthiness": "Precision mapping of the cosmic microwave background made cosmology a quantitative field and strongly constrained the universe's age, contents and history.",
        "attribution": "Bennett and Page represent central experimental leadership; Spergel represents a major role in extracting cosmological implications. The distinction between measurement and interpretation should guide the credit.",
        "maturity": "The measurements have been tested against later observations, and the cosmological framework they helped establish has endured.",
        "uncertainties": [
          "The boundary between decisive instrument and mission contributions and the wider WMAP team's work is difficult to capture with three laureates."
        ]
      }
    },
